from pov import Tree


class TreeTests(unittest.TestCase):
    def setUp(self):
        self.tree = Tree("0", [
            Tree("1", [Tree("4"), Tree("5")]),
            Tree("2", [Tree("6"), Tree("7")]),
            Tree("3", [Tree("8"), Tree("9")]),
        ])

    def test_reroot_at_leaf_preserves_all_branches(self):
        expected = Tree("6", [Tree("2", [
            Tree("7"),
            Tree("0", [
                Tree("1", [Tree("4"), Tree("5")]),
                Tree("3", [Tree("8"), Tree("9")]),
            ]),
        ])])
        self.assertEqual(self.tree.from_pov("6"), expected)

    def test_reroot_at_internal_node(self):
        expected = Tree("2", [Tree("6"), Tree("7"), Tree("0", [
            Tree("1", [Tree("4"), Tree("5")]),
            Tree("3", [Tree("8"), Tree("9")]),
        ])])
        self.assertEqual(self.tree.from_pov("2"), expected)

    def test_reroot_at_current_root(self):
        self.assertEqual(self.tree.from_pov("0"), self.tree)

    def test_single_node(self):
        tree = Tree("only")
        self.assertEqual(tree.from_pov("only"), tree)
        self.assertEqual(tree.path_to("only", "only"), ["only"])

    def test_paths_in_both_directions(self):
        self.assertEqual(self.tree.path_to("6", "9"), ["6", "2", "0", "3", "9"])
        self.assertEqual(self.tree.path_to("9", "6"), ["9", "3", "0", "2", "6"])
        self.assertEqual(self.tree.path_to("0", "7"), ["0", "2", "7"])
        self.assertEqual(self.tree.path_to("7", "0"), ["7", "2", "0"])
        self.assertEqual(self.tree.path_to("4", "5"), ["4", "1", "5"])
        self.assertEqual(self.tree.path_to("2", "2"), ["2"])

    def test_operations_do_not_mutate_original(self):
        original = str(self.tree)
        rerooted = self.tree.from_pov("6")
        self.tree.path_to("6", "9")
        rerooted.children[0].children[0].label = "changed"
        self.assertEqual(str(self.tree), original)
        self.assertEqual(self.tree.from_pov("6").from_pov("0"), self.tree)

    def test_missing_root(self):
        with self.assertRaisesRegex(ValueError, "^Tree could not be reoriented$"):
            self.tree.from_pov("missing")

    def test_missing_path_start(self):
        with self.assertRaisesRegex(ValueError, "^Tree could not be reoriented$"):
            self.tree.path_to("missing", "0")

    def test_missing_path_end(self):
        with self.assertRaisesRegex(ValueError, "^No path found$"):
            self.tree.path_to("0", "missing")

    def test_both_path_nodes_missing(self):
        with self.assertRaisesRegex(ValueError, "^Tree could not be reoriented$"):
            self.tree.path_to("missing", "also missing")


if __name__ == "__main__":
    unittest.main()
